// The gaps this port still carries against the reference managed shell.
//
// Generated from a failing run of the replay in `session_parity_tests.rs` and
// kept honest by two tests there: a difference no entry names fails the suite,
// and an entry whose difference no longer reproduces fails it too. Every entry
// belongs to row 6 of `docs/parity.md`, which is the row this ledger lowers.
//
// Entries are at field granularity, which is what NFR "no ledger entry is
// scoped wider than one field on one case" asks for: `/modelText` is one
// field, `/sessions/0/manifest/shell` is one field, and `/typedResult` alone
// would be thirteen.

/// The story that writes the session record the reference declares.
const US_296: &str = "US-296";
/// The story that mints session identifiers in the reference's format.
const US_297: &str = "US-297";
/// The story that bounds a managed window the way the reference bounds it.
const US_301: &str = "US-301";
/// The story that answers an empty chunk for a log file that is not there.
const US_303: &str = "US-303";
/// The story that records what is left in the divergence tables.
const US_306: &str = "US-306";

const WHY_RENDERED: &str = "the rendered text is the typed document read back one field per \
    line, so it carries whatever field that document still diverges on for this case (FR-05)";
const WHY_MESSAGE: &str = "the sentence the reference publishes for this action is \
    reference-authored text no committed artifact may carry, so the corpus holds a digest of it \
    and this port answers its own wording";
const WHY_LINE_ENDINGS: &str = "this port's managed terminal writes CRLF into the session log \
    where the reference's writes LF, so the raw window differs while the normalized `stdout` \
    matches";
const WHY_MAX_CHARS: &str = "the reference validates `max_bytes` through an alias that also \
    accepts `max_chars` and this port reads only `max_bytes`, so the alias does not bound the \
    window here";
const WHY_MANAGED_WINDOW: &str = "this port bounds a managed command window with the inline \
    budget where the reference bounds it with the output budget (FR-11)";
const WHY_RECORD: &str = "the session record carries this port's camelCase fields and millisecond \
    stamps rather than the reference's eleven snake_case fields with ISO-8601 timestamps (FR-06)";
const WHY_SESSION_ID: &str = "this port mints an epoch-milliseconds identifier where the reference \
    mints a UTC `%Y%m%d_%H%M%S` stamp (FR-07)";
const WHY_MISSING_LOG: &str = "the reference answers an empty chunk for a log file that is not \
    there and this port refuses (FR-13)";
const WHY_SHELL: &str = "the reference resolves its shell from the environment and accepts a \
    `shell` configuration key, which is how the capture pinned /bin/bash; this port has no such \
    key and starts /bin/sh, so the difference is recorded rather than closed";
const WHY_ERROR_KIND: &str = "the reference refuses these arguments inside the handler and raises \
    its tool error, and this port refuses them at the schema boundary, so both refuse and the \
    kind differs";
const WHY_EMPTY_ARGUMENT: &str = "the reference refuses an empty argument where this port accepts \
    it and answers, so the outcome kind differs on a case neither implementation runs a command \
    for";
const WHY_KILLED_SESSION: &str = "the reference keeps answering for a session it killed and this \
    port stops knowing it, so an inspection after a kill returns there and refuses here";

/// Builds one entry. Every gap this ledger holds belongs to [`SHELL_ROW`],
/// which is the row the replay lowers, so the row is not spelled 2 500 times.
const fn gap(
    tool: &'static str,
    case: &'static str,
    pointer: &'static str,
    closed_by: &'static str,
    why: &'static str,
) -> Divergence {
    Divergence {
        tool,
        case,
        pointer,
        closed_by,
        row: SHELL_ROW,
        why,
    }
}

